import { useState } from "react";
import { NavLink, Link } from "react-router-dom";
import {
  LayoutDashboard, Users, UserPlus, Receipt, ArrowRight, Link2, Settings,
  ChevronRight, ChevronsLeft, ChevronsRight, IndianRupee,
} from "lucide-react";
import { useAuth } from "../auth";

const mainLinks = [
  { to: "/", label: "Overview", icon: LayoutDashboard },
  { to: "/groups", label: "Groups", icon: Users },
  { to: "/friends", label: "Friends", icon: UserPlus },
  { to: "/expenses", label: "Expenses", icon: Receipt },
  { to: "/settlements", label: "Settlements", icon: ArrowRight },
];

const quickLinks = [
  { to: "/join-group", label: "Join a group", icon: Link2 },
  { to: "/settings", label: "Settings", icon: Settings },
];

function NavItem({ item, collapsed }) {
  const Icon = item.icon;
  return (
    <NavLink
      to={item.to}
      end={item.to === "/"}
      title={collapsed ? item.label : undefined}
      className={({ isActive }) =>
        `flex items-center rounded-xl font-medium transition-colors ${
          collapsed ? "justify-center p-3.5" : "gap-4 px-5 py-3.5"
        } ${isActive ? "bg-brand/30 text-white" : "text-slate-300 hover:bg-white/5 hover:text-white"}`
      }
    >
      <Icon size={20} strokeWidth={1.8} />
      {!collapsed && <span className="flex-1">{item.label}</span>}
    </NavLink>
  );
}

function Sidebar() {
  const { user } = useAuth();
  const [collapsed, setCollapsed] = useState(() => localStorage.getItem("sidebarCollapsed") === "true");

  const toggle = () => {
    localStorage.setItem("sidebarCollapsed", String(!collapsed));
    setCollapsed(!collapsed);
  };

  const sectionLabel = "px-3 mb-3 font-mono text-[11px] tracking-widest text-slate-500 uppercase";

  return (
    <aside
      className={`flex shrink-0 h-screen flex-col overflow-y-auto bg-ink text-white py-6 transition-all duration-200 ${
        collapsed ? "w-20 px-3" : "w-64 xl:w-72 px-4"
      }`}
    >
      <div className={`flex items-center mb-10 ${collapsed ? "flex-col gap-4" : "justify-between px-2"}`}>
        <Link to="/" className="flex items-center gap-3">
          <div className="w-11 h-11 rounded-xl bg-brand flex items-center justify-center">
            <IndianRupee size={22} />
          </div>
          {!collapsed && (
            <span className="text-2xl font-bold tracking-tight">
              fair<span className="text-brand">share</span>
            </span>
          )}
        </Link>
        <button
          onClick={toggle}
          aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/5 transition-colors"
        >
          {collapsed ? <ChevronsRight size={20} /> : <ChevronsLeft size={20} />}
        </button>
      </div>

      {!collapsed && <p className={sectionLabel}>Menu</p>}
      <nav className="flex flex-col gap-1.5">
        {mainLinks.map((item) => (
          <NavItem key={item.to} item={item} collapsed={collapsed} />
        ))}
      </nav>

      {collapsed ? <div className="my-6 border-t border-white/10" /> : <p className={`${sectionLabel} mt-10`}>Quick links</p>}
      <nav className="flex flex-col gap-1.5">
        {quickLinks.map((item) => (
          <NavItem key={item.to} item={item} collapsed={collapsed} />
        ))}
      </nav>

      <Link
        to="/profile"
        title={collapsed ? user.name : undefined}
        className={`mt-auto flex items-center rounded-2xl bg-inkSoft hover:bg-white/10 transition-colors ${
          collapsed ? "justify-center p-2" : "gap-3 p-4"
        }`}
      >
        <div className="w-11 h-11 shrink-0 rounded-full border-2 border-brand bg-brand/20 flex items-center justify-center text-sm font-semibold">
          {user.initials}
        </div>
        {!collapsed && (
          <>
            <div className="flex-1 min-w-0">
              <p className="font-semibold leading-tight truncate">{user.name}</p>
              <p className="text-sm text-slate-400 truncate">@{user.username}</p>
            </div>
            <ChevronRight size={18} className="text-slate-400" />
          </>
        )}
      </Link>
    </aside>
  );
}

export default Sidebar;
